from fastapi import FastAPI, Query
from fastapi.testclient import TestClient
from typing import List, Optional
import pytest

app = FastAPI()

@app.get("/test1")
def test1(q: Optional[List[int]] = Query(None)):
    return q

@app.get("/test2")
def test2(q: list[int] | None = Query(None)):
    return q

client = TestClient(app)

def test_optional_list():
    # Test Optional[List[int]]
    response = client.get("/test1", params={"q": [1, 2]})
    assert response.json() == {"q": [1, 2]}
    response = client.get("/test1")
    assert response.json() == {"q": null}

def test_union_list():
    # Test list[int] | None
    response = client.get("/test2", params={"q": [1, 2]})
    assert response.json() == {"q": [1, 2]}
    response = client.get("/test2")
    assert response.json() == {"q": null}

if __name__ == "__main__":
    try:
        test_optional_list()
        print("test_optional_list passed")
        test_union_list()
        print("test_union_list passed")
    except Exception as e:
        print(f"Error: {e}")
EOF

